SELECT order_id, unit_price_bucket, unique_products FROM (SELECT order_id, CASE WHEN unit_price >= 340 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END AS unit_price_bucket, COUNT(DISTINCT unit_price) AS unique_products FROM order_items GROUP BY order_id, CASE WHEN unit_price >= 340 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END) AS s WHERE unique_products > 10 ORDER BY 2, order_id LIMIT 1
